<?php
declare(strict_types=1);require_once __DIR__.'/../config/database.php';$ok='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$code=strtoupper(trim((string)($_POST['staff_code']??'')));$name=trim((string)($_POST['name']??''));$password=(string)($_POST['password']??'');$secret=(string)($_POST['secret_code']??'');$role=in_array($_POST['role']??'', ['admin','staff'],true)?$_POST['role']:'admin';if(!preg_match('/^[A-Z0-9_-]{3,30}$/',$code)||mb_strlen($name)<2||strlen($password)<8||!preg_match('/^\d{6}$/',$secret))$error='ข้อมูลไม่ถูกต้อง';else try{$stmt=db()->prepare('INSERT INTO staff(staff_code,name,password_hash,secret_code_hash,role) VALUES(?,?,?,?,?)');$stmt->execute([$code,$name,password_hash($password,PASSWORD_DEFAULT),password_hash($secret,PASSWORD_DEFAULT),$role]);$ok='สร้างบัญชีสำเร็จ กรุณาลบหรือเปลี่ยนชื่อไฟล์ database/create_admin.php ก่อนใช้งานจริง';}catch(Throwable $e){$error='สร้างบัญชีไม่สำเร็จ รหัสอาจซ้ำหรือฐานข้อมูลยังไม่พร้อม';}}
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>สร้างผู้ดูแลระบบ</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="auth-wrap" style="min-height:100vh"><form class="auth-card" method="post"><h1>สร้าง Admin คนแรก</h1><p>ใช้ครั้งเดียวหลัง Import SQL</p><?php if($ok):?><div class="success"><?=e($ok)?></div><?php endif?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif?><label class="field">Staff Code<input name="staff_code" required></label><label class="field">ชื่อ<input name="name" required></label><label class="field">Password<input type="password" name="password" minlength="8" required></label><label class="field">Secret Code 6 หลัก<input type="password" inputmode="numeric" pattern="[0-9]{6}" name="secret_code" required></label><label class="field">Role<select name="role"><option value="admin">Admin</option><option value="staff">Staff</option></select></label><button class="btn full">สร้างบัญชี</button></form></div></body></html>
